insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A small AVA of about 5,774 acres near Los Alamos in northern Santa Barbara County, where the San Antonio Creek valley runs about 20 miles west to the Pacific. At establishment it had nine commercial vineyards on about 238 acres and one winery, and Syrah is its most planted grape.', 'Winkler Region II, about 25 miles from the ocean, in a transition between coast and inland: cool marine air and fog arrive along the San Antonio Creek valley.', 'Mostly sandstone and shale soils of the Paso Robles Formation (63%) and Careaga Sandstone (13%), sandy and quick-draining, with calcium from shale and a rare streak of limestone.', 'Syrah first, with Grenache, Viognier and Cabernet Franc.', 'Dry red wines, mainly Syrah and Grenache, and some Viognier.', array['Established 2020 (27 CFR 9.270)', 'About 5,774 acres (TTB final rule)', 'Nine vineyards on about 238 acres at establishment (TTB final rule)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.central-coast.alisos-canyon';
