-- united-states.california.central-coast.carmel-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A sheltered valley inland from Carmel in the Santa Lucia Range, west of the Salinas Valley. About 300 of its 19,000 acres are planted, many on hillsides, to Cabernet Sauvignon, Merlot and other Bordeaux varieties.', 'Coastal influence with moderate swings on the hillsides; the day-to-night difference draws out ripening.', 'San Andreas fine sandy loam and Arroyo Seco gravelly sandy loam.', 'Cabernet Sauvignon and Merlot, with other Bordeaux varieties, Chardonnay and Pinot Noir.', 'Dry red wines from Cabernet Sauvignon and Merlot, and some Chardonnay and Pinot Noir.', array['Established 1982 (27 CFR 9.58)', 'About 300 of 19,000 acres planted (Monterey County Vintners & Growers)', 'Elevations from about 203 to 2,762 feet (Monterey County Vintners & Growers)']::text[], 'PUBLISHED'
