-- united-states.california.central-coast.gabilan-mountains
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A mountain AVA of about 98,000 acres in the Gabilan Range, across the Monterey–San Benito county line east of the Salinas Valley. It holds the smaller Chalone and Mt. Harlan AVAs. At establishment it had six commercial vineyards, about 436 acres, and four wineries.', 'High and dry: the area averages about 2,370 feet, has fewer than 2.5 hours of fog or cloud a day from June to September (7 to 9 in the areas around it) and about 17 inches of rain a year.', 'Moderately coarse soils over granite bedrock, mainly of the Sheridan-Cieneba-Auberry association, rich in calcium from limestone and quick to drain.', 'Pinot Noir and Chardonnay, the grapes of Chalone and Mt. Harlan, which it contains.', 'Dry Pinot Noir and Chardonnay from high, limestone-rich sites.', array['Established 2022 (27 CFR 9.288)', 'About 98,000 acres in Monterey and San Benito counties (TTB final rule)', 'Six vineyards, about 436 acres, and four wineries at establishment (TTB final rule)', 'Contains the Chalone and Mt. Harlan AVAs']::text[], 'PUBLISHED'
