-- united-states.california.central-coast.gabilan-mountains.chalone
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A high bench below the Pinnacles in the Gabilan Range, across the Monterey–San Benito county line. It has the oldest producing vines in Monterey County, and soils with limestone and granite unusual in the region. About 300 acres are planted.', 'Warm and dry: the height, from about 1,200 to 2,300 feet, keeps it above most of the coastal fog, and rainfall is low.', 'Vista coarse sandy loam and the McCoy-Gilroy complex, over granite with limestone.', 'Chardonnay and Pinot Noir, with Pinot Blanc, Chenin Blanc and Syrah.', 'Dry Chardonnay, Pinot Noir, Pinot Blanc and Chenin Blanc.', array['Established 1982 (27 CFR 9.24)', 'About 300 acres planted (Monterey County Vintners & Growers)', 'Elevations from about 1,201 to 2,323 feet (Monterey County Vintners & Growers)', 'Lies within the Gabilan Mountains AVA']::text[], 'PUBLISHED'
