-- united-states.california.central-coast.gabilan-mountains.mt-harlan
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A small, high AVA of about 7,400 acres in the Gabilan Range in San Benito County, south of Hollister. Its boundary follows the 1,800-foot contour, and its only vineyards are Calera''s, planted on limestone, which is rare in California, at an average of about 2,200 feet. Pinot Noir is its main grape.', 'Cooled by the height, about 3 °F for every 1,000 feet, and by Pacific air that reaches it through Monterey Bay; part of the high, dry Gabilan Mountains area, with little summer fog.', 'Limestone-rich soils over granite bedrock in the Gabilan Range.', 'Pinot Noir first, with Chardonnay and Viognier.', 'Dry Pinot Noir and Chardonnay, and some Viognier.', array['Established 1990 (27 CFR 9.131)', 'Its boundary follows the 1,800-foot contour line (27 CFR 9.131)', 'About 7,400 acres; Calera''s are the only vineyards (Calera Wine Company)', 'Lies within the Gabilan Mountains AVA']::text[], 'PUBLISHED'
