-- united-states.california.central-coast.monterey
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A large AVA that runs almost the whole length of Monterey County, mostly along the Salinas Valley from Monterey Bay south toward the San Luis Obispo County line. It holds Arroyo Seco, Santa Lucia Highlands, Hames Valley, San Bernabe and San Lucas. About 40,000 acres are planted, and Chardonnay is more than half of them.', 'Cool to hot along its roughly 100-mile length: wind and fog from Monterey Bay funnel up the Salinas Valley in the afternoon, so the north is cool and the south warm, with a long growing season and little rain.', 'Loams and sandy loams on the valley floor and benches, from the Chualar and Garey series to Lockwood shaly loam in the south.', 'Chardonnay over half the vineyard, with Pinot Noir, Riesling, Cabernet Sauvignon, Merlot, Syrah and Sauvignon Blanc.', 'Dry Chardonnay and Pinot Noir, and red wines from the warmer south.', array['Established 1984 (27 CFR 9.98)', 'About 40,000 acres planted; Chardonnay over 50% (Monterey County Vintners & Growers)', 'Elevations from sea level to about 2,320 feet (Monterey County Vintners & Growers)']::text[], 'PUBLISHED'
