-- united-states.california.central-coast.monterey.arroyo-seco
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA around the Arroyo Seco, the "dry riverbed" that leaves the Santa Lucia Range through a gorge and spreads its stones across the Salinas Valley near Greenfield. The large river stones help drainage. About 7,000 acres are planted, led by Chardonnay and Riesling.', 'Moderate: partly sheltered from the Salinas Valley''s afternoon wind by the gorge and the hills.', 'Stony alluvial soils with large river cobbles: Garey sandy loam, Oceano loamy sand and Lockwood shaly loam.', 'Chardonnay and Riesling, with Pinot Noir, Zinfandel and Bordeaux and Rhône varieties.', 'Dry and off-dry Riesling, dry Chardonnay, and red wines.', array['Established 1983 (27 CFR 9.59)', 'About 7,000 acres planted (Monterey County Vintners & Growers)', 'Elevations from about 266 to 1,670 feet (Monterey County Vintners & Growers)']::text[], 'PUBLISHED'
