-- united-states.california.central-coast.paso-robles
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A large inland AVA in northern San Luis Obispo County, about 614,000 acres east of the Santa Lucia Range, with more than 40,000 acres of vines and over 200 wineries. It is split by the Salinas River into a cooler, hillier west side and warmer rolling plains in the east. In 2014 eleven smaller AVAs were established within it.', 'Warm, dry days and cool nights, with some of the widest day-to-night swings in California; marine air reaches the west through the Templeton Gap and other passes in the Santa Lucia Range, while the east is warmer and more continental.', 'Very varied: calcareous shale and limestone-derived soils on the western hills, and alluvial terraces and fans of the Salinas and Estrella rivers in the east.', 'Cabernet Sauvignon is about 39% of the vineyard, then Merlot, Syrah and Zinfandel, with Grenache, Mourvèdre, Petite Sirah and Viognier among many others.', 'Dry red wines from Cabernet Sauvignon, Zinfandel and Rhône varieties, Rhône-style whites and dry rosé.', array['Established 1983 (27 CFR 9.84)', 'About 614,000 acres with more than 40,000 acres of vines (Paso Robles Wine Country Alliance)', 'Eleven AVAs were established within it in 2014 (T.D. TTB-125)', 'Planted: Cabernet Sauvignon 39%, Merlot 14%, Syrah 9%, Zinfandel 8% (Paso Robles Wine Country Alliance)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.central-coast.paso-robles';
