-- united-states.california.central-coast.paso-robles.adelaida-district
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'The most northwestern of the Paso Robles districts, about 53,100 acres in the southern Santa Lucia Range, with the highest ground in the Paso Robles AVA at about 2,200 feet. Its limestone-rich hills are home to both Rhône and Bordeaux varieties, and Tablas Creek brought Rhône cuttings here.', 'Region II–III with a modest marine influence: cooling winds and fog from Estero Bay to the west, around 25 to 30 inches of rain, and summer swings from about 50 °F at dawn to 95 °F in the afternoon.', 'Shallow residual soils over bedrock from the middle member of the Monterey Formation, largely calcareous, with white chalky rock and limestone.', 'Cabernet Sauvignon and Syrah, with Grenache, Mourvèdre, Zinfandel, Roussanne and other Rhône and Bordeaux varieties.', 'Dry red wines from Rhône and Bordeaux varieties, and Rhône-style whites.', array['Established 2014 (27 CFR 9.238)', 'About 53,100 acres; elevations from about 900 to 2,200 feet (Paso Robles Wine Country Alliance)', 'Rainfall about 25 inches a year in the rule''s comparison (T.D. TTB-125)', 'Labels must also show "Paso Robles" (Cal. Bus. & Prof. Code §25244)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.central-coast.paso-robles.adelaida-district';
