-- united-states.california.central-coast.paso-robles.creston-district
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A district of about 47,000 acres in the southeast of the Paso Robles AVA, on an old erosional plateau at the base of the La Panza Range, drained by Huerhuero Creek. About 1,400 acres are planted, mostly between 1,000 and 1,300 feet, and Bordeaux varieties lead, above all Cabernet Sauvignon.', 'Region III, with about 11.5 inches of rain a year and day-to-night swings of about 25 to 35 °F; Pacific air through the Templeton Gap and cold air draining from the La Panza Range cool it.', 'Old, well-developed terrace and hillside soils from granitic and sedimentary rocks: sandy loams below and clay loams on the terraces and hillsides.', 'Mostly Bordeaux varieties, above all Cabernet Sauvignon, with Merlot, Syrah and Zinfandel.', 'Dry red wines, mainly Cabernet Sauvignon and Bordeaux-style blends.', array['Established 2014 (27 CFR 9.239)', 'About 47,000 acres with 1,400 or more planted (Paso Robles Wine Country Alliance)', 'Rainfall about 11.5 inches a year (T.D. TTB-125)', 'Labels must also show "Paso Robles" (Cal. Bus. & Prof. Code §25244)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.central-coast.paso-robles.creston-district';
