-- united-states.california.central-coast.paso-robles.el-pomar-district
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A district of about 21,300 acres in the centre of the Paso Robles AVA, south of the town of Paso Robles, on high older terraces, fans and hills from about 740 feet by the Salinas River to 1,600 feet. Slightly over 2,000 acres are planted.', 'Region II, cool for Paso Robles: marine air through the Templeton Gap, about 15 inches of rain and day-to-night swings of 20 to 35 °F in the warmer months.', 'Quaternary alluvial soils, loams to clay loams, some calcareous: Linne Calodo alkaline clay loams on the hillsides and Lockwood-Concepcion shaly loams lower down.', 'Bordeaux varieties, including Cabernet Sauvignon, Merlot and Cabernet Franc, and Rhône varieties such as Syrah and Grenache.', 'Dry red wines from Bordeaux and Rhône varieties.', array['Established 2014 (27 CFR 9.240)', 'About 21,300 acres, slightly over 2,000 planted (Paso Robles Wine Country Alliance)', 'Elevations from about 740 to 1,600 feet (T.D. TTB-125)', 'Labels must also show "Paso Robles" (Cal. Bus. & Prof. Code §25244)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.central-coast.paso-robles.el-pomar-district';
