-- united-states.california.central-coast.paso-robles.paso-robles-estrella-district
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'The rolling plains and terraces of the Estrella River valley in the northeast of the Paso Robles AVA, about 66,800 acres from 745 to 1,800 feet. The name, Spanish for "star", refers to ridgelines that meet like the rays of a star. Estrella River Winery planted Syrah here in 1975, the source of the Estrella clone.', 'Region III with a modest marine influence: warm summer days cooled by sea breezes through the Templeton Gap and winds off the eastern ranges, 12.5 to 15.5 inches of rain, and day-to-night swings of 35 to 40 °F.', 'Quaternary alluvial soils of different ages on younger and older terraces, from fine sandy loams to clay loams.', 'Cabernet Sauvignon, Syrah, Merlot and Petite Sirah, with Sauvignon Blanc, Viognier and Chardonnay.', 'Dry red wines from Cabernet Sauvignon and Syrah, and some whites.', array['Established 2014 (27 CFR 9.241)', 'About 66,800 acres (Paso Robles Wine Country Alliance)', 'Estrella River Winery planted Syrah here in 1975 (Paso Robles Wine Country Alliance)', 'The legal name already includes "Paso Robles"']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.central-coast.paso-robles.paso-robles-estrella-district';
