-- united-states.california.central-coast.paso-robles.paso-robles-geneseo-district
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A district of about 17,300 acres east of the town of Paso Robles, on upfaulted hills and old river terraces along the Huerhuero–La Panza fault, from 740 to 1,300 feet. German settlers founded the Geneseo community in the 1880s, and the Ernst family planted vines in 1884; some of Paso Robles''s oldest Syrah grows here.', 'Region III–IV, with about 13 to 14 inches of rain; the Templeton Gap brings Pacific air, and day-to-night swings reach up to 50 °F.', 'Old alluvial terrace and residual hillside soils of moderate depth, often cemented: silty clays and clay loams with calcareous material beneath.', 'Bordeaux varieties and Rhône varieties, especially Syrah, with Cabernet Sauvignon and Zinfandel.', 'Dry red wines from Bordeaux and Rhône varieties.', array['Established 2014 (27 CFR 9.242)', 'About 17,300 acres; elevations 740 to 1,300 feet (Paso Robles Wine Country Alliance)', 'The Ernst family planted the first vines in 1884 (Paso Robles Wine Country Alliance)', 'The legal name already includes "Paso Robles"']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.central-coast.paso-robles.paso-robles-geneseo-district';
insert into public.wine_place_styles (wine_place_id, style, sort_order, editorial_status)
select id, 'RED', 0, 'PUBLISHED' from public.wine_places where canonical_key = 'united-states.california.central-coast.paso-robles.paso-robles-geneseo-district';
