  from public.wine_places p, public.grapes g
 where p.canonical_key = 'united-states.california.central-coast.paso-robles.paso-robles-geneseo-district' and g.name = 'Zinfandel';

-- united-states.california.central-coast.paso-robles.paso-robles-highlands-district
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'The second-largest Paso Robles district, about 60,300 acres in the far southeast, some 33 miles from the ocean, on an old erosional surface from 1,160 to 2,086 feet. Most vineyards lie between 1,200 and 1,600 feet, and harvest can come two to four weeks earlier than elsewhere in Paso Robles.', 'Region IV, warmer and more continental, with about 12 inches of rain and the widest swings in the AVA: summer highs around 100 °F and lows around 50 °F.', 'Deep, sometimes cemented alluvial soils and old leached alkaline soils: sandy loams by the creeks, loams on small fans, and coarse sandy loams to clay loams on the hillsides.', 'Cabernet Sauvignon, Petite Sirah and Syrah, with Zinfandel, Chardonnay and Sauvignon Blanc among more than 20 varieties.', 'Dry red wines from Cabernet Sauvignon, Petite Sirah and Syrah.', array['Established 2014 (27 CFR 9.243)', 'About 60,300 acres, the second-largest Paso Robles district (Paso Robles Wine Country Alliance)', 'Day-to-night swings of 50 °F or more in the rule''s comparison (T.D. TTB-125)', 'The legal name already includes "Paso Robles"']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.central-coast.paso-robles.paso-robles-highlands-district';
