-- united-states.california.central-coast.paso-robles.paso-robles-willow-creek-district
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A small, mountainous district west of the town of Paso Robles, named after the Willow Creek watershed at its centre, with conical hills from about 960 to 1,900 feet. It holds the Ueberroth Vineyard, planted in the late 1880s and called the oldest in the Paso Robles region; about 1,400 acres are planted.', 'Region II, among the coolest parts of Paso Robles: fog and breezes from the Templeton Gap, and 24 to 30 inches of rain, with day-to-night swings of about 20 °F.', 'Mostly shallow residual soils over bedrock from the middle and lower Monterey Formation, largely calcareous loams to clay loams.', 'Rhône varieties lead, Syrah, Grenache and Mourvèdre, with Zinfandel, Cabernet Sauvignon, Viognier and Roussanne.', 'Dry Rhône-style reds and whites, Zinfandel and some dry rosé.', array['Established 2014 (27 CFR 9.244)', 'About 1,400 acres under vine (Paso Robles Wine Country Alliance)', 'Rainfall 24 to 30 inches a year (T.D. TTB-125)', 'The legal name already includes "Paso Robles"']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.central-coast.paso-robles.paso-robles-willow-creek-district';
