-- united-states.california.central-coast.paso-robles.san-juan-creek
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A district of about 26,000 acres in the far east of the Paso Robles AVA, on the young river valleys, terraces and fans of San Juan Creek, a tributary of the upper Estrella River, from 980 to 1,600 feet. A little over 3,000 acres are planted.', 'Warm, Region III–IV, and dry, with about 10 inches of rain a year, but nights stay cool: day-to-night swings average 35 to 40 °F.', 'Deep, well to moderately drained alluvial soils: loamy sands, gravelly to sandy clay loams and a few clays.', 'Cabernet Sauvignon, Merlot and Cabernet Franc, with Petite Sirah and Zinfandel.', 'Dry red wines from Bordeaux varieties and Petite Sirah.', array['Established 2014 (27 CFR 9.245)', 'About 26,000 acres, a little over 3,000 planted (Paso Robles Wine Country Alliance)', 'Rainfall about 10.4 inches a year (T.D. TTB-125)', 'Labels must also show "Paso Robles" (Cal. Bus. & Prof. Code §25244)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.central-coast.paso-robles.san-juan-creek';
