-- united-states.california.central-coast.paso-robles.san-miguel-district
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'The northern tip of the Paso Robles AVA, around the town of San Miguel, on the footslopes of the Santa Lucia Range and the terraces of the Salinas and Estrella rivers, from 580 to 1,600 feet. Some of the area''s first grapes were planted at Mission San Miguel.', 'Region III, with about 11.4 inches of rain and day-to-night swings of 30 to 35 °F.', 'Deep alluvial sandy loams to loams and a few clay loams, from the river bottoms up onto higher terraces.', 'Cabernet Sauvignon and Zinfandel, with Syrah, Petite Sirah, Mourvèdre and Italian varieties such as Sangiovese and Aglianico.', 'Dry red wines from Cabernet Sauvignon, Zinfandel and Rhône and Italian varieties.', array['Established 2014 (27 CFR 9.246)', 'Elevations from about 580 to 1,600 feet (T.D. TTB-125)', 'Mission San Miguel''s vines were among the area''s first (Paso Robles Wine Country Alliance)', 'Labels must also show "Paso Robles" (Cal. Bus. & Prof. Code §25244)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.central-coast.paso-robles.san-miguel-district';
