-- united-states.california.central-coast.paso-robles.santa-margarita-ranch
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'The southernmost Paso Robles district and the only one that borders no other district, on the steep slopes and old river terraces of the upper Salinas River near the town of Santa Margarita. Its only vineyard is Ancient Peaks Winery''s Margarita Vineyard, planted in 1999, with blocks on fossil oyster-bed soils.', 'Region II, one of the coolest parts of Paso Robles, with about 29 inches of rain and day-to-night swings of about 25 °F; the growing season is long.', 'Deep alluvial soils of many rock types and textures, with patchy residual soils on the slopes, including calcareous fossil oyster beds.', 'Cabernet Sauvignon, Syrah and Zinfandel, with Merlot, Pinot Noir and Chardonnay.', 'Dry red wines from Cabernet Sauvignon, Syrah and Zinfandel, and some whites.', array['Established 2014 (27 CFR 9.247)', 'Elevations from about 900 to 1,400 feet (T.D. TTB-125)', 'Its only vineyard, the Margarita Vineyard, was planted in 1999 (Ancient Peaks Winery)', 'Labels must also show "Paso Robles" (Cal. Bus. & Prof. Code §25244)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.central-coast.paso-robles.santa-margarita-ranch';
