-- united-states.california.central-coast.paso-robles.templeton-gap-district
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A district of about 35,000 acres in the southwest of the Paso Robles AVA, around Templeton, where gaps in the Santa Lucia Range let cool afternoon air from the Pacific flow inland. Adolph Siot planted the first vineyard here in 1856, and the name "Templeton Gap" was coined in 1982.', 'Region II, about 2,900 growing degree days: cool afternoon winds through the passes in the Santa Lucia Range, about 20 inches of rain and day-to-night swings of about 20 °F; harvest can come up to two weeks later than nearby.', 'Alluvial terraces and fans of Paso Robles Creek and the Salinas River over bedrock, shallow to moderately deep, sandy to silty clay loams, calcareous in places.', 'Zinfandel and Cabernet Sauvignon, with Syrah and Merlot, and some Pinot Noir and Chardonnay in the coolest spots.', 'Dry red wines from Zinfandel, Cabernet Sauvignon and Syrah.', array['Established 2014 (27 CFR 9.248)', 'About 35,000 acres and some 20 wineries (Paso Robles Wine Country Alliance)', 'Adolph Siot planted the first vineyard in 1856 (Paso Robles Wine Country Alliance)', 'Labels must also show "Paso Robles" (Cal. Bus. & Prof. Code §25244)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.central-coast.paso-robles.templeton-gap-district';
insert into public.wine_place_styles (wine_place_id, style, sort_order, editorial_status)
