-- united-states.california.central-coast.san-francisco-bay
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A large AVA around San Francisco Bay, mainly in San Francisco, San Mateo, Santa Clara, Alameda and Contra Costa counties and partly in Santa Cruz and San Benito. It groups the bay''s wine areas, including Livermore Valley, Santa Clara Valley, Lamorinda and the Santa Cruz Mountains, which overlap it. When it was established, nearly 5,800 acres were planted and over 39 wineries operated.', 'A marine climate shaped by the bay and the Pacific: fog and low cloud come through the Golden Gate and other gaps, cooling summer days and warming winter nights, with heat increasing inland; the South Bay averages about 18 inches of rain a year.', 'Varied: alluvial valley floors, gravel in Livermore Valley and mountain soils in the Santa Cruz range.', 'Cabernet Sauvignon and Chardonnay are the most planted, with Petite Sirah, Zinfandel and Pinot Noir.', 'Dry red and white wines, from Cabernet Sauvignon and Zinfandel to Chardonnay.', array['Established 1999 (27 CFR 9.157)', 'About 2,448 square miles in seven counties (T.D. ATF-407)', 'Nearly 5,800 acres planted at establishment (T.D. ATF-407)', 'The same rule extended the Central Coast AVA to include it (T.D. ATF-407)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.central-coast.san-francisco-bay';
insert into public.wine_place_styles (wine_place_id, style, sort_order, editorial_status)
select id, 'RED', 0, 'PUBLISHED' from public.wine_places where canonical_key = 'united-states.california.central-coast.san-francisco-bay';
