-- united-states.california.central-coast.san-francisco-bay.livermore-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An east–west valley in Alameda County, east of San Francisco Bay, and one of California''s oldest wine regions. Robert Livermore planted vines in the 1840s, and Carl H. Wente and James Concannon founded wineries in 1883. In 1889 a Livermore dry white won the Grand Prix at the Paris Exposition, and the first varietally labelled Chardonnay came from Wente in 1936.', 'Warm afternoons cooled by marine breezes and fog: heat rising over the Central Valley to the east pulls cool bay air through the valley in the late afternoon.', 'Mainly gravel, which drains freely and limits vigour.', 'Cabernet Sauvignon and Chardonnay lead, with Sauvignon Blanc, Semillon, Petite Sirah and Zinfandel; nearly 80% of California''s Chardonnay vines trace back to a Livermore Valley clone.', 'Dry reds from Cabernet Sauvignon and Petite Sirah, and dry whites from Chardonnay, Sauvignon Blanc and Semillon.', array['Established 1982 (27 CFR 9.46)', 'More than 3,000 acres of vineyards and over 40 wineries (Livermore Valley Winegrowers)', 'Wente and Concannon founded their wineries in 1883 (Livermore Valley Winegrowers)', 'Wente made the first varietally labelled Chardonnay in 1936 (Livermore Valley Winegrowers)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.central-coast.san-francisco-bay.livermore-valley';
