-- united-states.california.central-coast.san-francisco-bay.santa-cruz-mountains
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A mountain AVA in San Mateo, Santa Clara and Santa Cruz counties, between the Pacific and Monterey Bay on one side and San Francisco Bay and the Santa Clara Valley on the other. It was the first California AVA whose borders follow the mountains'' elevation, geology and vegetation rather than a valley. It has more than 80 wineries and some 200 growers, and its vineyards have been noted since the 1870s.', 'Cooled by the ocean on the western side and warmer on the eastern slopes facing the bay; many vineyards lie above the fog.', 'Variable mountain soils, from sandstone and shale to decomposed rock, on steep slopes cut by the San Andreas fault system.', 'Pinot Noir, Cabernet Sauvignon and Chardonnay, with Merlot and Zinfandel.', 'Dry Pinot Noir, Cabernet Sauvignon and Chardonnay.', array['Established 1981 (27 CFR 9.31)', 'Its boundary follows the 400-, 600- and 800-foot contour lines in places (27 CFR 9.31)', 'Elevations from 400 feet to over 3,000 feet (Santa Cruz Mountains Winegrowers)', 'More than 80 wineries and 200 growers (Santa Cruz Mountains Winegrowers)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.central-coast.san-francisco-bay.santa-cruz-mountains';
