-- united-states.california.central-coast.san-luis-obispo-coast
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A coastal AVA of about 408,500 acres along the San Luis Obispo County coast, from coastal terraces and foothills to small valleys that open westward to the Pacific. It holds Edna Valley and Arroyo Grande Valley, and 97% of it lies at or below 1,800 feet, about the limit of the ocean''s influence. At establishment it had about 78 vineyards on 3,942 acres.', 'Region I on the Winkler scale, about 2,493 growing degree days: marine air moderates both heat and cold, and fog covers the coast on 35 to 55 percent of growing-season nights.', 'Four main groups: Franciscan sandstone and shale, marine sandy loams and loams, soils from volcanic intrusions, and wind-blown coastal sands.', 'Chardonnay (43%) and Pinot Noir (35%) dominate, with Syrah, Albariño, Riesling and Grenache.', 'Dry Chardonnay and Pinot Noir, aromatic whites, and some Syrah.', array['Established 2022 (27 CFR 9.282)', 'About 408,505 acres; 97% at or below 1,800 feet (TTB final rule)', 'About 78 vineyards on 3,942 acres; Chardonnay 43%, Pinot Noir 35% (TTB final rule)', 'May also be labelled "SLO Coast" (TTB final rule)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.central-coast.san-luis-obispo-coast';
insert into public.wine_place_styles (wine_place_id, style, sort_order, editorial_status)
