-- united-states.california.central-coast.san-luis-obispo-coast.arroyo-grande-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A valley south of Edna Valley that runs inland from the coast near Arroyo Grande, within the SLO Coast AVA. It grows Pinot Noir, Chardonnay and Zinfandel, and sparkling wine is made here; Talley and Laetitia are among its producers.', 'Fog covers the parts nearest the ocean much of the day and keeps them mild and steady; the valley''s inland reaches are more sheltered from direct marine influence.', 'Clay and loam soils shared with the SLO Coast, on terraces and valley floors.', 'Pinot Noir and Chardonnay, with Zinfandel and Syrah.', 'Dry Pinot Noir and Chardonnay, Zinfandel, and sparkling wine.', array['Established 1990 (27 CFR 9.129)', 'More sheltered from direct marine influence than the open coast (TTB final rule, 2022)', 'Lies within the San Luis Obispo Coast AVA']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.central-coast.san-luis-obispo-coast.arroyo-grande-valley';
