-- united-states.california.central-coast.san-luis-obispo-coast.edna-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A small valley southeast of the city of San Luis Obispo, open to marine air, within the SLO Coast AVA. It is known above all for Chardonnay; the Paragon Vineyard, planted in 1973, began its modern era.', 'Cool and marine: mostly Region II with Region I pockets, with ocean air that keeps acidity high in the grapes.', 'Clay and loam soils of marine sedimentary origin, with limestone in places.', 'Chardonnay above all, with Pinot Noir, Syrah and Albariño.', 'Dry Chardonnay and Pinot Noir, and aromatic whites.', array['Established 1982 (27 CFR 9.35)', 'Mostly Region II, with Region I pockets (TTB final rule, 2022)', 'The Paragon Vineyard was planted in 1973 (Tasting Table)', 'Lies within the San Luis Obispo Coast AVA']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.central-coast.san-luis-obispo-coast.edna-valley';
