-- united-states.california.central-coast.santa-maria-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A broad valley on the Santa Barbara–San Luis Obispo county line, running east–west and open to the Pacific, so ocean wind and fog flow straight up it. It was California''s second AVA, after Napa Valley, and grows mostly Chardonnay and Pinot Noir. The Bien Nacido Vineyard was planted in 1973.', 'Cool, Region I: fog comes in off the ocean most mornings and afternoons, the wind is steady, and summer days stay around the mid-70s °F, giving one of the longest growing seasons in California.', 'Sandy and loamy soils on the valley floor and benches, well drained.', 'Chardonnay and Pinot Noir, with Syrah as the third grape.', 'Dry Chardonnay and Pinot Noir, and cool-climate Syrah.', array['Established 1981 (27 CFR 9.28)', 'California''s second AVA (Santa Barbara Vintners)', 'Spans Santa Barbara and San Luis Obispo counties', 'About 7,500 acres of vineyards (Santa Maria Valley Wine Country)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.central-coast.santa-maria-valley';
