-- united-states.california.central-coast.santa-ynez-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A long east–west valley in Santa Barbara County, the Santa Ynez River''s, that opens to the Pacific at Lompoc and runs inland past Buellton, Solvang and Los Olivos toward Lake Cachuma. Temperatures rise by about a degree for every mile from the sea, so it grows Pinot Noir and Chardonnay in the west, Rhône varieties in the middle and Bordeaux varieties in the east. It holds Sta. Rita Hills, Ballard Canyon, Los Olivos District and Happy Canyon of Santa Barbara.', 'Cool in the west and warm in the east: fog settles on the vines at night and clears by midday, and a single vineyard often sees swings of more than 50 °F between day and night.', 'Varied: marine sands and sedimentary soils in the west, alluvial terraces in the middle, and serpentine-rich soils in the far east.', 'Chardonnay, Pinot Noir and Syrah lead, with Sauvignon Blanc, Cabernet Sauvignon and Grenache.', 'Dry reds and whites from Burgundy, Rhône and Bordeaux varieties, and some dry rosé.', array['Established 1983 (27 CFR 9.54)', 'Contains Sta. Rita Hills, Ballard Canyon, Los Olivos District and Happy Canyon of Santa Barbara', 'Temperature rises about 1 °F per mile inland (Santa Barbara Vintners)', 'County plantings 2023: Chardonnay 3,471 acres, Pinot Noir 2,913, Syrah 975 (Santa Barbara Vintners)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.central-coast.santa-ynez-valley';
insert into public.wine_place_styles (wine_place_id, style, sort_order, editorial_status)
select id, 'RED', 0, 'PUBLISHED' from public.wine_places where canonical_key = 'united-states.california.central-coast.santa-ynez-valley';
