-- united-states.california.central-coast.santa-ynez-valley.ballard-canyon
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A small north–south canyon of about 7,800 acres between Solvang, Buellton and Los Olivos, in the middle of the Santa Ynez Valley. About 550 acres are planted, and its growers focus on Syrah: over half the vineyard is Syrah and another 30% other Rhône varieties.', 'In between the cool west and warm east of the valley; the north–south canyon brings its own pattern of wind, fog and marine influence.', 'Soils of the canyon''s slopes and floor within the Santa Ynez Valley''s sedimentary hills.', 'Syrah over half the vineyard, with Grenache, Viognier and Roussanne making up about 30% more.', 'Dry red wines, above all Syrah, and Rhône-style whites.', array['Established 2013 (27 CFR 9.230)', 'About 7,800 acres, 550 planted (Santa Barbara Vintners)', 'Over half the vineyard is Syrah (Santa Barbara Vintners)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.central-coast.santa-ynez-valley.ballard-canyon';
