-- united-states.california.central-coast.santa-ynez-valley.happy-canyon-of-santa-barbara
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'The far eastern end of the Santa Ynez Valley, northeast of Santa Ynez near Lake Cachuma, about 23,900 acres of foothills rising from 500 to about 3,430 feet. It is the warmest part of the valley and grows mainly Bordeaux varieties. "of Santa Barbara" was added to the name because the United States has several other Happy Canyons.', 'The warmest part of the Santa Ynez Valley, about 3,340 growing degree days: a north–south ridge blocks the Pacific breezes, and rainfall averages about 16 inches.', 'Alluvial soils below and upland soils above, with green serpentine parent material that gives high magnesium levels, and loams and clay loams with chert and serpentine cobbles.', 'Cabernet Sauvignon, Sauvignon Blanc, Cabernet Franc, Merlot and Petit Verdot, with Syrah and other Rhône varieties.', 'Dry Bordeaux-style reds and dry Sauvignon Blanc.', array['Established 2009 (27 CFR 9.217)', 'About 23,941 acres, with 492 acres of vineyard in 6 vineyards at establishment (TTB final rule)', 'About 3,340 growing degree days (TTB final rule)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.central-coast.santa-ynez-valley.happy-canyon-of-santa-barbara';
