-- united-states.california.central-coast.santa-ynez-valley.los-olivos-district
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A broad alluvial terrace of the Santa Ynez River, about 22,820 acres around Los Olivos, Ballard, Santa Ynez and Solvang, in the middle of the Santa Ynez Valley. With about 1,120 acres in 47 vineyards at establishment, it holds the largest concentration of vineyards among the valley''s sub-AVAs, including several of its older vineyards.', 'About 30 miles inland, with less marine fog than the west: warm days and cool nights.', 'More than 95% from the Positas-Ballard-Santa Ynez association: moderately to well drained gravelly fine sandy loams and clay loams of low to moderate fertility, on gently sloping ground.', 'Sauvignon Blanc, Cabernet Sauvignon and Cabernet Franc, with Syrah and other Rhône varieties, and some Spanish and Italian varieties.', 'Dry Sauvignon Blanc and dry reds from Bordeaux and Rhône varieties.', array['Established 2016 (27 CFR 9.253)', 'About 22,820 acres (TTB final rule)', 'About 47 vineyards on 1,120 acres and 12 wineries at establishment (TTB final rule)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.central-coast.santa-ynez-valley.los-olivos-district';
