-- united-states.california.central-coast.santa-ynez-valley.sta-rita-hills
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'The western end of the Santa Ynez Valley between Buellton and Lompoc, a corridor of hills between the Purisima Hills and the Santa Rosa Hills along the Santa Ynez River. Established as Santa Rita Hills, it was renamed Sta. Rita Hills in 2006 after an objection from the Chilean producer Viña Santa Rita. More than 59 vineyards grow about 2,700 acres, mostly Pinot Noir and Chardonnay.', 'Cool, Region I: fog in the mornings and afternoon ocean breezes; the establishing rule found it markedly cooler during ripening than the Santa Ynez Valley to the east.', 'A high share of alluvial and marine sands, with sedimentary soils and patches of diatomaceous earth and limestone.', 'Pinot Noir and Chardonnay, with Syrah among some 18 other varieties.', 'Dry Pinot Noir and Chardonnay, and cool-climate Syrah.', array['Established 2001 (27 CFR 9.162)', 'Renamed from Santa Rita Hills to Sta. Rita Hills, effective 2006 (T.D. TTB-37)', 'Over 59 vineyards on about 2,700 acres (Santa Barbara Vintners)', 'Elevations from sea level to about 1,800 feet (TTB final rule)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.central-coast.santa-ynez-valley.sta-rita-hills';
