-- united-states.california.central-valley.lodi
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A large AVA at the northern end of the San Joaquin Valley, around the city of Lodi in San Joaquin and Sacramento counties, beside the Sacramento–San Joaquin River Delta. It grows more than 100 varieties, but Zinfandel leads: Lodi crushes about 40% of California''s Zinfandel, and it has many old vines. In 2006 seven smaller AVAs were established within it.', 'Mediterranean: warm days and cool evenings, when the "Delta breeze" draws cool air from San Francisco Bay through the Delta, even in high summer.', 'Deep, well-drained sandy loams around the city of Lodi in the west, and older clays and cobbly volcanic soils in the eastern foothills.', 'Zinfandel above all, with Cabernet Sauvignon, Chardonnay, Merlot, Petite Sirah and Syrah among more than 100 varieties.', 'Dry red wines, above all Zinfandel, dry whites and dry rosé.', array['Established 1986 (27 CFR 9.107)', 'Seven AVAs were established within it in 2006 (TTB final rule, 2006)', 'Crushes about 40% of California''s Zinfandel (Lodi Winegrape Commission)', 'Lodi Rules (2005) was California''s first third-party-certified sustainable winegrowing program']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.central-valley.lodi';
