-- united-states.california.central-valley.lodi.alta-mesa
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A "high table" of river terraces in Sacramento County, in the north of the Lodi AVA, about 55,400 acres with some 5,000 planted. It is one of the warmer parts of Lodi, and its flat, mesa-like surface gives it its name.', 'Warmer than the Delta side, with more than 200 degree days above Jahant and Mokelumne River; a mean annual temperature of about 60.5 °F and about 18.5 inches of rain.', 'About 90% San Joaquin series, dense heavy clay, on flat terraces between 35 and 138 feet.', 'Zinfandel, Cabernet Sauvignon, Syrah, Merlot and Cabernet Franc, with Tempranillo.', 'Dry red wines from Zinfandel and Bordeaux and Rhône varieties.', array['Established 2006 (27 CFR 9.195)', 'About 55,400 acres, some 5,000 planted (TTB final rule, 2006)', 'Elevations from about 35 to 138 feet (TTB final rule, 2006)']::text[], 'PUBLISHED'
