-- united-states.california.central-valley.lodi.borden-ranch
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'Old alluvial fans, terraces and hills on the eastern side of the Lodi AVA, across the Sacramento–San Joaquin county line, rising from 73 to 520 feet toward the Sierra foothills. About 70,000 acres, with more than 11,000 planted. It is named after the ranch Ivey Lewis Borden set up in 1864.', 'Windier, warmer and wetter than the western lowlands, with about 20 inches of rain and strong winds from the Delta and down from the Sierra.', 'The oldest soils in the valley, with heavy surface cobble: Redding, Hicksville, Corning and Yellowlark series, and old volcanic clays.', 'Mostly red: Zinfandel, Cabernet Sauvignon, Merlot, Petite Sirah, Syrah and Petit Verdot, with Chardonnay and Sauvignon Blanc.', 'Dry red wines from Zinfandel and Bordeaux and Rhône varieties, and some whites.', array['Established 2006 (27 CFR 9.196)', 'About 70,000 acres, more than 11,000 planted (TTB final rule, 2006)', 'Elevations from 73 to 520 feet (TTB final rule, 2006)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.central-valley.lodi.borden-ranch';
