-- united-states.california.central-valley.lodi.clements-hills
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'Rounded hills in the southeast of the Lodi AVA, entirely in San Joaquin County, where the San Joaquin Valley floor meets the Sierra foothills, from about 90 to over 400 feet. About 85,400 acres with some 16,000 planted, it is named after the town of Clements, itself named in 1882 after the settler Thomas Clements.', 'Warmer and wetter than the western Lodi areas, with less fog and wind; about 21 to 22 inches of rain a year.', 'Old red, brown and yellow loams, clay loams and clays of the Redding, Cometa, Yellowlark and Montpellier series, with granitic and volcanic sediment; some deep sandy loams hold old own-rooted Zinfandel.', 'Zinfandel and Cabernet Sauvignon, with Petite Sirah, Merlot, Syrah, Barbera, Tempranillo and Chardonnay.', 'Dry red wines from Zinfandel, Bordeaux, Rhône and Spanish varieties.', array['Established 2006 (27 CFR 9.197)', 'About 85,400 acres, some 16,000 planted (TTB final rule, 2006)', 'Rainfall about 21 to 22 inches a year (TTB final rule, 2006)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.central-valley.lodi.clements-hills';
