-- united-states.california.central-valley.lodi.cosumnes-river
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'The low, wet northwest corner of the Lodi AVA along the Cosumnes River, near sea level to about 48 feet, among wetlands, levees and sloughs next to the Delta. About 54,700 acres, with some 3,000 planted at establishment. The name comes from a Miwok term.', 'The coolest of the seven Lodi AVAs, with a mean annual temperature of about 60 °F, persistent fog and a cool, breezy growing season; about 17.4 inches of rain.', 'About 60% young, moderately fertile silty soils of the floodplains, and 40% reddish gravelly clay loams of the San Joaquin series.', 'Chardonnay, Sauvignon Blanc and Pinot Gris, with Cabernet Sauvignon, Merlot, Syrah and Vermentino.', 'Dry white wines from Chardonnay, Sauvignon Blanc and Pinot Gris, and some reds.', array['Established 2006 (27 CFR 9.198)', 'About 54,700 acres (TTB final rule, 2006)', 'Elevations from near sea level to about 48 feet (TTB final rule, 2006)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.central-valley.lodi.cosumnes-river';
