-- united-states.california.central-valley.lodi.jahant
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'The smallest of the seven Lodi AVAs, about 28,000 acres of river terraces and old floodplain in the centre of the Lodi AVA, dotted with lakes and sloughs, from 10 to 100 feet. About 8,000 acres are planted. It is named after Peter Jahant and his brothers, settlers of the 1850s; Charles Jahant planted 130 acres of grapes in 1912.', 'Cool, dry and windy, with long spells of Delta wind and marine fog; mean annual temperature about 60.1 °F and about 18 inches of rain.', 'Pink Rocklin-Jahant loam, sandy loams and sandy clay loams whose clay holds enough water for some dry-farming.', 'Zinfandel, Petite Sirah and Tempranillo among the most planted, with Cabernet Sauvignon and Chardonnay.', 'Dry red wines from Zinfandel, Petite Sirah and Tempranillo.', array['Established 2006 (27 CFR 9.199)', 'About 28,000 acres, some 8,000 planted (TTB final rule, 2006)', 'Charles Jahant planted 130 acres of grapes in 1912 (TTB final rule, 2006)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.central-valley.lodi.jahant';
