-- united-states.california.central-valley.lodi.mokelumne-river
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'The heart of the Lodi AVA around the city of Lodi, a young alluvial fan of the Mokelumne River, about 85,700 acres with some 42,000 planted, over 40% of Lodi''s vineyard. Its deep sandy loams hold many old, own-rooted Zinfandel vines.', 'Among the coolest parts of Lodi: strong Delta winds blow more than 70% of the time, and degree days run 50 to 450 below the other areas; about 17.6 inches of rain.', 'Deep, well-drained Tokay and Acampo sandy loams, in places 50 to 100 feet deep before hardpan, low in water-holding capacity.', 'Zinfandel above all, including old own-rooted vines, with Cabernet Sauvignon, Chardonnay, Petite Sirah, Carignan and Cinsault.', 'Dry red wines, above all old-vine Zinfandel, and dry whites.', array['Established 2006 (27 CFR 9.200)', 'About 85,700 acres, some 42,000 planted (TTB final rule, 2006)', 'Elevations from about 5 to 100 feet (TTB final rule, 2006)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.central-valley.lodi.mokelumne-river';
