-- united-states.california.central-valley.lodi.sloughhouse
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'The northeastern corner of the Lodi AVA in Sacramento County, the most varied terrain of the seven, from rolling hills and plains to the Sierra bedrock foothills, 73 to 590 feet. About 78,800 acres with some 7,000 planted, it is named after the Sloughhouse Inn, a stagecoach stop of the 1850s.', 'The warmest and wettest of the Lodi AVAs, with little marine influence and less fog; mean annual temperature about 61.6 °F and about 23 inches of rain.', 'Older alluvial fan soils of the Redding, Corning, Pentz and Hadlesville series in the west, and old soils from metamorphic and volcanic rock higher up.', 'Mostly red: Zinfandel, Cabernet Sauvignon, Petite Sirah, Syrah, Grenache and Mourvèdre, with Chardonnay and Sauvignon Blanc.', 'Dry red wines from Zinfandel, Bordeaux and Rhône varieties.', array['Established 2006 (27 CFR 9.201)', 'About 78,800 acres, some 7,000 planted (TTB final rule, 2006)', 'The warmest of the seven Lodi AVAs (TTB final rule, 2006)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.central-valley.lodi.sloughhouse';
