-- united-states.california.el-dorado
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA covering the wine-growing part of El Dorado County in the Sierra Nevada foothills, between the North Fork of the American River and the Cosumnes River, east of Sacramento. Its vineyards are among the highest in California, mostly between 2,500 and 3,500 feet, and vines were first planted here during the Gold Rush of the 1850s. It overlaps much of the Sierra Foothills AVA and holds Fair Play.', 'Mountain climate: warm, sunny days above the fog, cool nights, winter snow on the vines, high summer UV and later ripening than the valley below.', 'Granitic soils and volcanic and sedimentary deposits, well drained.', 'Zinfandel, Syrah and Barbera lead, with Cabernet Sauvignon, Merlot, Grenache, Viognier and Chardonnay.', 'Dry red wines from Zinfandel, Rhône and Italian varieties, and dry whites.', array['Established 1983 (27 CFR 9.61)', 'Bounded by the North Fork of the American River and the South Fork of the Cosumnes River (27 CFR 9.61)', 'Most vineyards lie between 2,500 and 3,500 feet (El Dorado Winery Association)', 'Contains the Fair Play AVA']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.el-dorado';
insert into public.wine_place_styles (wine_place_id, style, sort_order, editorial_status)
select id, 'RED', 0, 'PUBLISHED' from public.wine_places where canonical_key = 'united-states.california.el-dorado';
