-- united-states.california.el-dorado.fair-play
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A high area of rolling hills in southern El Dorado County, about 33 square miles around the old Gold Rush mining camp of Fair Play, within both the El Dorado and Sierra Foothills AVAs. Horace Bigelow founded the first commercial vineyard in 1887. At establishment it had about 350 acres of vines, 250 in production.', 'High Region III, under 3,500 degree days, with 35 to 40 inches of rain in an average year and a growing season of about 230 to 250 days.', 'Deep, moderately to well-drained granitic soils of the Holland, Shaver and Musick series, sandy loams and coarse sandy loams.', 'Zinfandel is the most planted red, with Syrah, Barbera, Grenache and other Rhône and Italian varieties.', 'Dry red wines from Zinfandel and Rhône and Italian varieties, and some whites.', array['Established 2001 (27 CFR 9.168)', 'Vineyards from about 2,000 to 2,800 feet (ATF final rule, 2001)', 'About 350 acres of vines at establishment (ATF final rule, 2001)', 'Named after a Gold Rush mining camp (ATF final rule, 2001)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.el-dorado.fair-play';
