-- united-states.california.north-coast.clear-lake
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'The largest AVA in Lake County, nearly 220,000 acres around Clear Lake, California''s largest natural freshwater lake wholly within the state. Vineyards sit high, from about 1,300 feet at the lakeshore to the slopes of Mount Konocti and beyond. It holds Red Hills Lake County, Big Valley District, Kelsey Bench and Upper Lake Valley.', 'High and inland, with warm days and cold nights; the lake moderates temperatures near its shore, and the elevation makes this one of the cooler inland growing areas in California.', 'Alluvial soils on the valley floors around the lake and rocky red volcanic soils on the flanks of Mount Konocti, a dormant volcano.', 'Cabernet Sauvignon and Sauvignon Blanc lead, with Zinfandel, Petite Sirah and Merlot.', 'Dry red wines, mainly Cabernet Sauvignon, and dry Sauvignon Blanc.', array['Established 1984 (27 CFR 9.99)', 'Nearly 220,000 acres, the largest AVA in Lake County (Lake County Winegrape Commission)', 'Elevations from about 1,300 feet (Lake County Winegrape Commission)', 'Lake County''s first vineyards were planted in the 1870s (Discover California Wines)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.north-coast.clear-lake';
