-- united-states.california.north-coast.clear-lake.red-hills-lake-county
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'Rolling hills on the southwest shore of Clear Lake, between Lower Lake and Kelseyville, at the foot of Mount Konocti. The hills take their name from iron-red volcanic soil scattered with black obsidian from the volcano''s eruptions. Most of its vines grow at 2,000 feet or higher, and Cabernet Sauvignon leads.', 'High-elevation and sunny, with cool nights; the lake and the height keep the growing season temperate.', 'Red, iron-rich, stony volcanic soils with black obsidian, quartz crystals and volcanic gravel.', 'Cabernet Sauvignon above all, with Cabernet Franc, Petite Sirah, Syrah, Zinfandel and Sauvignon Blanc.', 'Dry red wines, chiefly Cabernet Sauvignon.', array['Established 2004 (27 CFR 9.169)', 'Its boundary follows contour lines from 1,400 to 3,000 feet (27 CFR 9.169)', 'Most vines are planted at 2,000 feet or higher (Lake County Winegrape Commission)', 'Boundary amended in 2024 (T.D. TTB-190)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.north-coast.clear-lake.red-hills-lake-county';
