-- united-states.california.north-coast.fountaingrove-district
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA of about 38,000 acres on the Mayacamas slopes northeast of Santa Rosa, between the Russian River Valley, Knights Valley and Sonoma Valley. It is named after the Fountain Grove colony that Thomas Lake Harris founded in 1875, whose winery Kanaye Nagasawa later ran. About 500 acres are planted.', 'Warm, Region II on the Winkler scale: warmer than the Russian River Valley but more marine-influenced than Alexander Valley and northern Napa.', 'Rolling hills with soils from Sonoma Volcanics and Franciscan Formation bedrock.', 'Cabernet Sauvignon, with Chardonnay, Sauvignon Blanc, Merlot, Cabernet Franc, Zinfandel and Syrah.', 'Dry red wines led by Cabernet Sauvignon, and dry whites.', array['Established 2015 (27 CFR 9.250)', 'About 38,000 acres, 500 of them planted (Sonoma County Tourism)', 'Named after the Fountain Grove colony of 1875 (Sonoma County Tourism)', 'Labels must also show "Sonoma County" (Cal. Bus. & Prof. Code §25246)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.north-coast.fountaingrove-district';
