-- united-states.california.north-coast.los-carneros
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A low, rolling AVA at the north shore of San Pablo Bay, spanning the southern ends of Napa and Sonoma counties. It was the first AVA defined by its climate rather than by geography, and it is known for Pinot Noir, Chardonnay and sparkling wine. The name, "the rams", dates from Mexican land grants of the 1830s, and the land was sheep ranches, dairies and hay fields before vines took over in the 1970s.', 'Cool and windy: marine air and fog come straight off San Pablo Bay, summer days rarely pass 80 °F, the difference between day and night is small, and rainfall, at up to about 24 inches, is the lowest in Napa Valley.', 'Shallow, dense clay soils, not very fertile, over a hard claypan that keeps roots near the surface and holds yields down; loams and hillside alluvium in the north.', 'Pinot Noir and Chardonnay above all, with Merlot, Syrah and some Cabernet Sauvignon.', 'Dry Pinot Noir and Chardonnay, and sparkling wine made from both.', array['Established 1983 (27 CFR 9.32)', 'Spans Napa and Sonoma counties', 'Over 8,000 acres of vineyard (Napa Valley Vintners)', 'Elevations from sea level to about 700 feet (Napa Valley Vintners)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.north-coast.los-carneros';
insert into public.wine_place_styles (wine_place_id, style, sort_order, editorial_status)
