-- united-states.california.north-coast.mendocino
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'The main AVA of Mendocino County, north of Sonoma, taking in the inland valleys along the upper Russian River around Ukiah, Hopland and Redwood Valley, and the Anderson Valley toward the coast. It holds Anderson Valley, McDowell Valley, Potter Valley, Redwood Valley and Yorkville Highlands. Much of the county is redwood forest, and vines were first planted here in 1850.', 'Contrasting: Anderson Valley, open to the Pacific, is cool and foggy, while the inland valleys behind the coastal ranges are warm and dry in summer.', 'Alluvial soils on the valley floors of the Russian River and its tributaries, and older, often red, well-drained soils on the benches and hills.', 'Chardonnay, Cabernet Sauvignon and Pinot Noir make up most of the county''s crop, followed by Zinfandel, Merlot, Sauvignon Blanc and Syrah.', 'Dry whites and reds from Chardonnay, Cabernet Sauvignon, Pinot Noir and Zinfandel, and sparkling wine from Anderson Valley.', array['Established 1984 (27 CFR 9.93)', 'Contains Anderson Valley, McDowell Valley, Potter Valley, Redwood Valley and Yorkville Highlands', '2022 county crush: Chardonnay 38%, Cabernet Sauvignon 22.4%, Pinot Noir 12.4% (USDA crush report)', 'About 60% of Mendocino County is redwood forest (Discover California Wines)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.north-coast.mendocino';
insert into public.wine_place_styles (wine_place_id, style, sort_order, editorial_status)
