-- united-states.california.north-coast.mendocino.anderson-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A narrow valley following the Navarro River northwest toward the Pacific, through Boonville and Philo, in Mendocino County. Its northwest end is only a few miles from the ocean. It grows Pinot Noir and Chardonnay, Alsace varieties such as Gewürztraminer and Riesling, and base wine for sparkling wine; about 2,457 acres are planted in some 90 vineyards.', 'Cool and marine: Pacific fog follows the Navarro River into the valley on summer nights and burns off by midday; inland around Boonville days are warmer, and the valley averages about 53 °F over the year.', 'Clay on the valley flats and loams over sandstone and shale on the benches and hillsides.', 'Pinot Noir first, with Chardonnay and the Alsace varieties Gewürztraminer, Riesling and Pinot Gris.', 'Dry Pinot Noir and Chardonnay, aromatic dry whites, and traditional-method sparkling wine.', array['Established 1983 (27 CFR 9.86)', 'About 2,457 acres planted in some 90 vineyards (Anderson Valley Winegrowers Association)', 'Average annual temperature about 53 °F (Anderson Valley Winegrowers Association)', 'Lies within the Mendocino AVA']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.north-coast.mendocino.anderson-valley';
