-- united-states.california.north-coast.mendocino-ridge
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA made only of coastal ridge-tops in Mendocino County, at or above 1,200 feet, a few miles from the Pacific. The outer boundary encloses about 262,400 acres, but only the 87,466 acres above 1,200 feet count, so the AVA is a scatter of separate hilltops. When it was established there were about 75 acres of vines in six vineyards, many of them Zinfandel.', 'Cool and coastal: the ridge-tops are cooler by day and warmer by night than the valley floors, a difference of about 10 °F, and the grapes keep high natural acidity.', 'Well-drained "timber" soils of sandstone mixed with loamy clay on narrow, forested ridge-tops; the rule judged only about 2% of the land above 1,200 feet suitable for vines.', 'Zinfandel above all, including old plantings, with some Pinot Noir and Syrah.', 'Dry red wines, mainly Zinfandel from ridge-top vineyards.', array['Established 1997 (27 CFR 9.158)', 'Includes only land at or above 1,200 feet (TTB final rule, T.D. ATF-392)', '87,466 of 262,400 enclosed acres lie above 1,200 feet (T.D. ATF-392)', 'About 75 acres of vines in six vineyards at establishment (T.D. ATF-392)', 'About 209 acres now planted in 18 vineyards (Zinfandel Advocates & Producers)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.north-coast.mendocino-ridge';
insert into public.wine_place_styles (wine_place_id, style, sort_order, editorial_status)
select id, 'RED', 0, 'PUBLISHED' from public.wine_places where canonical_key = 'united-states.california.north-coast.mendocino-ridge';
