-- united-states.california.north-coast.napa-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'California''s first AVA, a valley about 30 miles long between the Mayacamas Mountains to the west and the Vaca Range to the east, in Napa County. Fifteen smaller AVAs lie within it, from Calistoga at the northern end to Coombsville and Oak Knoll District near the city of Napa, and Los Carneros and Wild Horse Valley overlap its southern edge. It is known above all for Cabernet Sauvignon.', 'A dry Mediterranean climate: warm, rainless summers and mild, wet winters. Fog and wind from San Pablo Bay cool the southern end, and the valley grows warmer toward Calistoga in the north; the mountain AVAs above the fog line see fewer swings between day and night.', 'Very varied over short distances: gravelly and sandy alluvial fans and river deposits on the valley floor, volcanic soils from ash and lava on the eastern side and in the hills, and marine sedimentary soils on the western slopes.', 'Cabernet Sauvignon above all, with Merlot, Cabernet Franc and the other Bordeaux varieties; Chardonnay and Sauvignon Blanc for whites; Zinfandel and Pinot Noir in smaller amounts.', 'Dry red wines, mostly Cabernet Sauvignon and Bordeaux-style blends, dry whites from Chardonnay and Sauvignon Blanc, and sparkling wine from the cooler south.', array['Established 1981 (27 CFR 9.23)', 'California''s first AVA', 'About 30 miles long and a few miles wide (Napa Valley Vintners)', 'Grows about 4% of California''s wine grapes (Napa Valley Vintners)', 'Wines naming an AVA wholly inside Napa County must also show "Napa Valley" on the label (Cal. Bus. & Prof. Code §25240)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.north-coast.napa-valley';
insert into public.wine_place_styles (wine_place_id, style, sort_order, editorial_status)
select id, 'RED', 0, 'PUBLISHED' from public.wine_places where canonical_key = 'united-states.california.north-coast.napa-valley';
