-- united-states.california.north-coast.napa-valley.atlas-peak
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A mountain AVA on the western slopes of the Vaca Range, east of the Stags Leap District and the city of Napa, named after the 2,663-foot Atlas Peak. Most of the area lies above 1,400 feet, above much of the valley fog. Wines labelled Atlas Peak must also carry the Napa Valley name.', 'A cool mountain climate with less fog than the valley floor: summer days are about 10 to 15 °F cooler than on the valley floor and rarely pass 90 °F, and the difference between day and night is wide.', 'Volcanic soils, often red and basaltic, shallow and quick-draining, so vineyards usually need irrigation.', 'Mainly Cabernet Sauvignon and Chardonnay.', 'Dry red wines, above all Cabernet Sauvignon, and dry Chardonnay.', array['Established 1992 (27 CFR 9.140)', 'Part of its boundary follows the 1,600-foot contour line (27 CFR 9.140)', 'Elevations from about 760 to 2,600 feet; most of the area lies above 1,400 feet (Napa Valley Vintners)', 'Labels must also show "Napa Valley" (Cal. Bus. & Prof. Code §25240)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.north-coast.napa-valley.atlas-peak';
insert into public.wine_place_styles (wine_place_id, style, sort_order, editorial_status)
select id, 'RED', 0, 'PUBLISHED' from public.wine_places where canonical_key = 'united-states.california.north-coast.napa-valley.atlas-peak';
