-- united-states.california.north-coast.napa-valley.calistoga
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'The northernmost AVA on the Napa Valley floor, around the town of Calistoga below Mount St. Helena, closed in by mountains on three sides. It is the warmest part of the valley floor, and its soils are largely volcanic. Wines labelled Calistoga must also carry the Napa Valley name.', 'Warm to hot days, with summer peaks above 100 °F, and cold nights that can fall to the low 40s °F as air drains down from the surrounding mountains; one of the widest day-to-night swings in Napa Valley.', 'Mostly volcanic: rocky and stony loams on the hillsides, gravelly and cobbly loams on the alluvial fans, and heavier clay and silt toward the centre of the valley.', 'Cabernet Sauvignon first, with Zinfandel, Petite Sirah, Merlot, Cabernet Franc and Sauvignon Blanc.', 'Dry red wines, from Cabernet Sauvignon to Zinfandel and Petite Sirah, and some Sauvignon Blanc.', array['Established 2009 (27 CFR 9.209)', 'Elevations from about 300 to 1,200 feet (Napa Valley Vintners)', 'The town was named in 1867 by Samuel Brannan (Napa Valley Vintners)', 'Labels must also show "Napa Valley" (Cal. Bus. & Prof. Code §25240)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.north-coast.napa-valley.calistoga';
