-- united-states.california.north-coast.napa-valley.chiles-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A long, narrow valley in the Vaca Range in the northeast of Napa County, higher and set apart from the main Napa Valley. It has more vineyards than wineries, and it is named after Joseph Ballinger Chiles, who received a land grant here in 1841. Wines labelled Chiles Valley must also carry the Napa Valley name.', 'Warm summer days, typically in the mid-80s °F, and cool nights below 50 °F because of the elevation; winters and springs are colder than on the Napa Valley floor, and harvest comes later.', 'Mostly of marine origin: fertile alluvial silty clay on the valley floor and clay loams and stony clays on the hillsides, with some volcanic outcrops.', 'Cabernet Sauvignon, Merlot and Zinfandel, with some Cabernet Franc and Sauvignon Blanc.', 'Dry red wines, mainly Cabernet Sauvignon, Merlot and Zinfandel.', array['Established 1999 (27 CFR 9.154)', 'Elevations from about 600 to 1,200 feet (Napa Valley Vintners)', 'The first winery here was founded in the 1870s by Francis Sievers (Napa Valley Vintners)', 'Labels must also show "Napa Valley" (Cal. Bus. & Prof. Code §25240)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.north-coast.napa-valley.chiles-valley';
