-- united-states.california.north-coast.napa-valley.coombsville
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A horseshoe of hills directly east of the city of Napa, at the foot of the Vaca Range, near the southern end of Napa Valley. It is mostly vineyards, with few wineries, and was known first for Chardonnay and Pinot Noir before Cabernet Sauvignon took over. Wines labelled Coombsville must also carry the Napa Valley name.', 'Cool for Napa Valley: San Pablo Bay is close, marine fog comes in most days of the growing season, and in the hottest months average highs can run up to 10 °F below those of other Napa AVAs.', 'Largely volcanic: rhyolitic tuff and old lava flows with plenty of rock, gravel and ash on the uplands, and alluvial soils in the lower parts.', 'Cabernet Sauvignon, Chardonnay and Merlot, with Pinot Noir and Syrah.', 'Dry red wines, above all Cabernet Sauvignon, and dry Chardonnay.', array['Established 2011 (27 CFR 9.223)', 'Elevations from about 100 to 1,000 feet (Napa Valley Vintners)', 'Rainfall up to about 25 inches a year (Napa Valley Vintners)', 'Labels must also show "Napa Valley" (Cal. Bus. & Prof. Code §25240)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.north-coast.napa-valley.coombsville';
insert into public.wine_place_styles (wine_place_id, style, sort_order, editorial_status)
