-- united-states.california.north-coast.napa-valley.crystal-springs-of-napa-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A hillside AVA of about 4,000 acres on the western face of the Vaca Range, east of St. Helena and south of Howell Mountain. It covers slopes between 400 and 1,400 feet, with no flat ground, and about 230 acres of vineyard in some 30 commercial vineyards when it was established in 2024. It was Napa Valley''s first new AVA in 13 years.', 'The slopes face west and southwest and receive more sun than north- or east-facing ground; below 1,400 feet they keep a maritime influence, and the final rule notes that ground above and below the band is more prone to frost.', 'Thin, well-drained volcanic soils, with volcanic ash on slopes of 15 to 40 percent.', 'Mainly Cabernet Sauvignon, planted on the hillside vineyards.', 'Dry red wines, chiefly Cabernet Sauvignon.', array['Established 2024 (27 CFR 9.296)', 'About 4,000 acres, with about 230 acres of vineyard at establishment (TTB final rule)', 'The 1,400-foot upper edge matches Howell Mountain''s southern boundary (TTB final rule)', 'The same rule redrew Calistoga''s boundary to put the Crystal Springs Vineyard wholly in this AVA']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.north-coast.napa-valley.crystal-springs-of-napa-valley';
insert into public.wine_place_styles (wine_place_id, style, sort_order, editorial_status)
