 where p.canonical_key = 'united-states.california.north-coast.napa-valley.crystal-springs-of-napa-valley' and g.name = 'Cabernet Sauvignon';

-- united-states.california.north-coast.napa-valley.diamond-mountain-district
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A mountain AVA in the Mayacamas range just south of Calistoga, at the northwest end of Napa Valley. Its name comes from shards of volcanic glass in the soil. Jacob Schram planted vines here in 1862. Wines labelled Diamond Mountain District must also carry the Napa Valley name.', 'Mostly above the fog line: summer days rarely pass 90 °F and run 10 to 15 °F cooler than on the valley floor, with smaller swings between day and night; Diamond Creek''s drainage brings cool air.', 'Reddish, fine-grained volcanic soils, sometimes gritty, weathered from uplifted volcanic and sedimentary rock; porous and quick-draining.', 'Cabernet Sauvignon dominates, with Cabernet Franc, Merlot and Petit Verdot.', 'Dry red wines, chiefly Cabernet Sauvignon and Bordeaux-style blends.', array['Established 2001 (27 CFR 9.166)', 'Elevations from about 400 to 2,200 feet (Napa Valley Vintners)', 'Named for the reflective volcanic glass in its soils (Napa Valley Vintners)', 'Labels must also show "Napa Valley" (Cal. Bus. & Prof. Code §25240)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.north-coast.napa-valley.diamond-mountain-district';
