-- united-states.california.north-coast.napa-valley.howell-mountain
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A plateau in the Vaca Range above St. Helena, around the village of Angwin, and the first AVA established inside Napa Valley. Its southern edge was set at 1,400 feet, where the fog tops out, so its vineyards lie above the valley''s fog. Wines labelled Howell Mountain must also carry the Napa Valley name.', 'Above the fog line on the eastern side of the valley: warmer and drier than much of Napa Valley, with more hours of sun and little marine influence.', 'Shallow volcanic soils of low fertility that drain freely, from iron-rich red soils to white compressed volcanic ash (tuff).', 'Cabernet Sauvignon above all, with Merlot, Zinfandel and Cabernet Franc; a little Chardonnay and Viognier.', 'Dry red wines, mostly Cabernet Sauvignon and Zinfandel, and a few whites.', array['Established 1983 (27 CFR 9.94)', 'The first sub-appellation of Napa Valley (Napa Valley Vintners)', 'Elevations from about 1,400 to 2,600 feet (Napa Valley Vintners)', 'Labels must also show "Napa Valley" (Cal. Bus. & Prof. Code §25240)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.north-coast.napa-valley.howell-mountain';
