-- united-states.california.north-coast.napa-valley.mt-veeder
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A mountain AVA on the eastern slopes of the Mayacamas range, northwest of the city of Napa, along the line between Napa and Sonoma. It is one of the larger Napa sub-AVAs but among the least planted, because the ground is steep and wooded. It is named after the 1850s pastor Peter Veeder. Wines labelled Mt. Veeder must also carry the Napa Valley name.', 'Cool for Napa: summer days run 10 to 15 °F below the valley floor, with mid-summer highs around 85 °F, and most vineyards sit above the fog line.', 'Shallow, acidic, sandy and sandy-loam soils of marine sedimentary origin, an old seabed with Franciscan mélange beneath and rare volcanic pockets; well drained and low in fertility.', 'Cabernet Sauvignon above all, with Zinfandel, Merlot, Chardonnay and Syrah.', 'Dry red wines, mainly Cabernet Sauvignon and Zinfandel, and dry Chardonnay.', array['Established 1990 (27 CFR 9.123)', 'Elevations from about 500 to 2,600 feet; most above 1,400 feet (Napa Valley Vintners)', 'Over 1,000 acres planted (Napa Valley Vintners)', 'Labels must also show "Napa Valley" (Cal. Bus. & Prof. Code §25240)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.north-coast.napa-valley.mt-veeder';
