-- united-states.california.north-coast.napa-valley.oak-knoll-district-of-napa-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A flat stretch of the valley floor at the southern end of central Napa Valley, just north of the city of Napa. Joseph Osborne planted vinifera vines here in 1851. The legal name ends in "of Napa Valley", so it already carries the valley''s name.', 'Cool and even: daily fog from San Pablo Bay and afternoon breezes give one of the valley''s coolest sub-AVAs and a long growing season; mid-summer highs reach about 92 °F and nights fall to about 50 °F.', 'River-laid soils in the centre, gravelly alluvial fans on the west side below Mt. Veeder, and silty clay loams toward the river in the south and east.', 'Cabernet Sauvignon, Chardonnay and Merlot, with Sauvignon Blanc and Riesling.', 'Dry red wines from Cabernet Sauvignon and Merlot, and dry whites from Chardonnay, Sauvignon Blanc and Riesling.', array['Established 2004 (27 CFR 9.161)', 'Over 4,150 acres planted (Napa Valley Vintners)', 'Elevations from sea level to about 800 feet (Napa Valley Vintners)', 'Growing season averages about eight months (Napa Valley Vintners)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.north-coast.napa-valley.oak-knoll-district-of-napa-valley';
insert into public.wine_place_styles (wine_place_id, style, sort_order, editorial_status)
