-- united-states.california.north-coast.napa-valley.oakville
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A valley-floor AVA in the middle of Napa Valley, running from the Mayacamas foothills on the west to the Vaca foothills on the east, between Yountville and Rutherford. About three quarters of its vineyard is Cabernet Sauvignon. Wines labelled Oakville must also carry the Napa Valley name.', 'Moderately warm, with summer days commonly in the mid-90s °F; evening and early-morning fog keeps acidity in the grapes, and the eastern side gets more afternoon sun.', 'Gravelly, sedimentary alluvial loams on the western side and heavier volcanic soils on the eastern side; fairly deep and well drained.', 'Cabernet Sauvignon above all, with Merlot, Cabernet Franc and Sauvignon Blanc.', 'Dry red wines, mainly Cabernet Sauvignon and Bordeaux-style blends, and dry Sauvignon Blanc.', array['Established 1993 (27 CFR 9.134)', 'Over 5,000 acres planted; about 75% Cabernet Sauvignon (Napa Valley Vintners)', 'Elevations from about 130 to 1,000 feet (Napa Valley Vintners)', 'Labels must also show "Napa Valley" (Cal. Bus. & Prof. Code §25240)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.north-coast.napa-valley.oakville';
