-- united-states.california.north-coast.napa-valley.rutherford
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A valley-floor AVA at the widest point of Napa Valley, between Oakville and St. Helena, from the Mayacamas benchland on the west to the Vaca foothills on the east. Georges de Latour''s Beaulieu winery made its name here after Prohibition. Wines labelled Rutherford must also carry the Napa Valley name.', 'Moderately warm, with summer peaks in the mid-90s °F, early-morning fog and a wide difference between day and night; the western bench is cooled by afternoon marine wind.', 'Sedimentary, gravelly and sandy alluvial soils on the western benchland and moderately deep volcanic soils on the eastern side; locals speak of "Rutherford dust" for the fine-grained tannin of the bench wines.', 'Cabernet Sauvignon dominates, with Merlot, Cabernet Franc and Sauvignon Blanc.', 'Dry red wines, mostly Cabernet Sauvignon and Bordeaux-style blends, and dry Sauvignon Blanc.', array['Established 1993 (27 CFR 9.133)', 'Elevations from about 155 to 500 feet (Napa Valley Vintners)', 'Rainfall up to about 38 inches a year (Napa Valley Vintners)', 'Labels must also show "Napa Valley" (Cal. Bus. & Prof. Code §25240)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.north-coast.napa-valley.rutherford';
