-- united-states.california.north-coast.napa-valley.spring-mountain-district
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A mountain AVA on the eastern slopes of the Mayacamas range directly west of St. Helena, with small vineyards cut into forest on steep, mostly east-facing ground. Charles Lemme is the first documented grape grower here, in 1874. Wines labelled Spring Mountain District must also carry the Napa Valley name.', 'Cool to moderate depending on height and aspect: warmer nights and cooler days than the valley floor, and the coolest, wettest of the Napa sub-AVAs.', 'Mostly sedimentary: weathered sandstone and shale, loamy and friable, well drained and low in fertility, over Franciscan mélange in the south; volcanic soils toward the north end.', 'Cabernet Sauvignon first, with Merlot, Cabernet Franc, Petite Sirah, Chardonnay and Riesling.', 'Dry red wines, mainly Cabernet Sauvignon, and some dry Chardonnay and Riesling.', array['Established 1993 (27 CFR 9.143)', 'Elevations from about 600 to 2,600 feet (Napa Valley Vintners)', 'About 30 miles from the Pacific (Napa Valley Vintners)', 'Labels must also show "Napa Valley" (Cal. Bus. & Prof. Code §25240)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.north-coast.napa-valley.spring-mountain-district';
