-- united-states.california.north-coast.napa-valley.st-helena
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An hourglass-shaped AVA around the town of St. Helena, taking in the narrowest part of Napa Valley between Rutherford and Calistoga. Charles Krug founded his winery here in 1861. Wines labelled St. Helena must also carry the Napa Valley name.', 'One of the warmer parts of the Napa Valley floor, at times hotter than Calistoga, with rainfall of about 40 inches a year.', 'Alluvial fans from both sides of the valley: gravelly loams on the western side and volcanic soils washed down from the eastern hills.', 'Cabernet Sauvignon first, with Merlot, Cabernet Franc, Zinfandel, Sauvignon Blanc and Chardonnay.', 'Dry red wines, mostly Cabernet Sauvignon, and dry whites.', array['Established 1995 (27 CFR 9.149)', 'Over 6,800 acres of vines in more than 400 vineyards (Napa Valley Vintners)', 'Elevations from about 400 to 800 feet (Napa Valley Vintners)', 'Labels must also show "Napa Valley" (Cal. Bus. & Prof. Code §25240)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.north-coast.napa-valley.st-helena';
