-- united-states.california.north-coast.napa-valley.stags-leap-district
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A small AVA on the east side of Napa Valley, about six miles north of the city of Napa, some three miles long and one mile wide between the Stags Leap palisades and the Napa River. In the 1976 Paris tasting a Stag''s Leap Wine Cellars Cabernet Sauvignon placed first among the reds. Wines labelled Stags Leap District must also carry the Napa Valley name.', 'Moderately warm, with mid-summer highs in the mid-90s °F and up to 100 °F; the palisades funnel cool afternoon air from San Pablo Bay through the district and cool the nights.', 'Volcanic gravelly loams on the valley floor and rocky hillsides, of low to moderate fertility over hard clay subsoils.', 'Cabernet Sauvignon dominates, with Merlot, Cabernet Franc, Petit Verdot and some Sauvignon Blanc.', 'Dry red wines, chiefly Cabernet Sauvignon and Bordeaux-style blends.', array['Established 1989 (27 CFR 9.117)', 'About 2,700 acres, over half planted (Napa Valley Vintners)', 'Elevations from sea level to about 400 feet (Napa Valley Vintners)', 'Labels must also show "Napa Valley" (Cal. Bus. & Prof. Code §25240)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.north-coast.napa-valley.stags-leap-district';
