-- united-states.california.north-coast.napa-valley.yountville
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A valley-floor AVA around the town of Yountville and its low hills, in the southern part of Napa Valley between Oak Knoll District and Oakville. It is named after George C. Yount, who planted the first vines here in the 1840s. Wines labelled Yountville must also carry the Napa Valley name.', 'Moderate, with a cool marine influence: fog and strong breezes from San Pablo Bay keep mid-summer peaks in the low 90s °F, and nights fall to the mid-50s °F.', 'Mainly gravelly silt loams of sedimentary origin and rocky alluvial soils of moderate fertility.', 'Cabernet Sauvignon and Merlot, with Chardonnay and Sauvignon Blanc.', 'Dry red wines from Cabernet Sauvignon and Merlot, and dry whites.', array['Established 1999 (27 CFR 9.160)', 'Over 3,000 acres planted (Napa Valley Vintners)', 'Elevations from about 20 to 200 feet (Napa Valley Vintners)', 'Labels must also show "Napa Valley" (Cal. Bus. & Prof. Code §25240)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.north-coast.napa-valley.yountville';
