-- united-states.california.north-coast.northern-sonoma
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A large umbrella AVA over northern Sonoma County that takes in Alexander Valley, Dry Creek Valley, Knights Valley, Russian River Valley and its sub-AVAs, from valley floors to mountain peaks. It was petitioned by E. & J. Gallo so that its Sonoma wines from vineyards in different valleys could carry one appellation, and few labels use it today.', 'Varied: cool and foggy toward the Russian River Valley and the coast, warmer in the inland valleys of Alexander and Knights Valley.', 'Varied, from river gravels and alluvium on the valley floors to volcanic and sedimentary soils in the hills.', 'Cabernet Sauvignon, Chardonnay and Zinfandel, with Sauvignon Blanc, Pinot Noir and Merlot.', 'Dry red and white wines, from Cabernet Sauvignon and Zinfandel to Chardonnay.', array['Established 1985 (27 CFR 9.70)', 'About 329,000 acres, Sonoma County''s second-largest AVA after Sonoma Coast (Sonoma County Tourism)', 'Petitioned by E. & J. Gallo (Sonoma County Tourism)', 'Labels must also show "Sonoma County" (Cal. Bus. & Prof. Code §25246)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.north-coast.northern-sonoma';
