-- united-states.california.north-coast.northern-sonoma.alexander-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'The valley of the upper Russian River in Sonoma County, from the Mendocino County line southeast to Healdsburg, with the Mayacamas range to the east. It is Sonoma County''s largest planted AVA, known for Cabernet Sauvignon since the 1960s and 1970s. It is named after the pioneer Cyrus Alexander; the Italian Swiss Colony was founded at Asti in the 1880s.', 'Warm days with heat spikes, tempered by cool marine air from the Pacific that brings cool evenings.', 'Alluvial soils laid down by the meandering Russian River over gravel deposits, with hillside soils on the benches and slopes.', 'Cabernet Sauvignon first, with Merlot and other Bordeaux varieties, Chardonnay, Sauvignon Blanc and old-vine Zinfandel.', 'Dry red wines, mostly Cabernet Sauvignon, and dry whites from Chardonnay and Sauvignon Blanc.', array['Established 1984 (27 CFR 9.53)', 'About 15,000 acres of vineyard (Sonoma County Tourism)', 'Named after the pioneer Cyrus Alexander (Sonoma County Tourism)', 'Labels must also show "Sonoma County" (Cal. Bus. & Prof. Code §25246)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.north-coast.northern-sonoma.alexander-valley';
