-- united-states.california.north-coast.northern-sonoma.dry-creek-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A narrow valley about 16 miles long and 2 miles wide northwest of Healdsburg, running from the Russian River up to Lake Sonoma. It is known above all for Zinfandel, including old vines that survived Prohibition when growers switched to prunes, and for Sauvignon Blanc. Over 70 wineries, mostly family-owned, work here.', 'In between the cooler Russian River Valley and warmer Alexander Valley: fog tempers the valley in the mornings without dominating it.', 'Very rocky, free-draining soils, planted on hillsides, benches and the valley floor.', 'Zinfandel first, with Sauvignon Blanc, Cabernet Sauvignon, Petite Sirah and the Rhône varieties Grenache, Syrah and Mourvèdre.', 'Dry red wines, above all Zinfandel, and dry Sauvignon Blanc.', array['Established 1983 (27 CFR 9.64)', 'Over 9,000 acres of vineyard (Sonoma County Tourism)', 'About 16 miles long and 2 miles wide (Sonoma County Tourism)', 'Labels must also show "Sonoma County" (Cal. Bus. & Prof. Code §25246)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.north-coast.northern-sonoma.dry-creek-valley';
