-- united-states.california.north-coast.northern-sonoma.knights-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A warm, high valley in eastern Sonoma County below Mount St. Helena, between Alexander Valley and Napa''s Calistoga, reached by Highway 128. It is named after Thomas B. Knight, and it has stayed rural: cattle and vineyards, few wineries. Cabernet Sauvignon and the other Bordeaux varieties lead.', 'Warm and inland, cut off from most of the coastal fog, with cooler air at night coming down from the surrounding hills.', 'Soils of the valley floor and of the lower slopes of Mount St. Helena, an old volcano that towers over the valley.', 'Cabernet Sauvignon and other Bordeaux varieties lead, with Sauvignon Blanc, Chardonnay and Syrah.', 'Dry red wines, mainly Cabernet Sauvignon, and dry Sauvignon Blanc.', array['Established 1983 (27 CFR 9.76)', 'About 2,000 acres of vineyard (Sonoma County Tourism)', 'Named after Thomas B. Knight (Sonoma County Tourism)', 'Labels must also show "Sonoma County" (Cal. Bus. & Prof. Code §25246)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.north-coast.northern-sonoma.knights-valley';
