-- united-states.california.north-coast.northern-sonoma.russian-river-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A cool AVA at the centre of Sonoma County, on the lower Russian River and the Santa Rosa Plain, from Healdsburg south toward Sebastopol and Santa Rosa. It does not follow the river all the way to the sea. Chardonnay and Pinot Noir are its main grapes, then Zinfandel. Most of it also lies inside the Sonoma Coast AVA, which overlaps it.', 'Warm days tempered by Pacific fog that lingers in the hills west of Sebastopol into the late afternoon; temperatures can drop 35 to 40 °F from day to night, and the growing season runs long.', 'Varied; the fine-grained Goldridge sandy loam, well drained and moderate in vigour, dominates its western Green Valley corner.', 'Chardonnay, Pinot Noir and Zinfandel lead by acreage, with Sauvignon Blanc, Syrah, Merlot and Pinot Gris.', 'Dry Chardonnay and Pinot Noir, Zinfandel, and sparkling wine from the cooler western parts.', array['Established 1983 (27 CFR 9.66)', 'Over 70 wineries (Sonoma County Tourism)', 'Its boundary has been amended several times since 1983 (27 CFR 9.66)', 'Labels must also show "Sonoma County" (Cal. Bus. & Prof. Code §25246)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.north-coast.northern-sonoma.russian-river-valley';
