-- united-states.california.north-coast.northern-sonoma.russian-river-valley.chalk-hill
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A hilly corner of the Russian River Valley east of Windsor, rising to about 1,600 feet toward Knights Valley. The pale soil that gave it its name is not chalk but white volcanic ash. It has more than 1,400 acres of vineyard but only a handful of wineries.', 'Warmer than most of the Russian River Valley, with less fog and steady breezes.', 'White, quartz-rich volcanic tuff (ash) that looks like chalk, with loams on the slopes.', 'Chardonnay and Sauvignon Blanc, with Cabernet Sauvignon, Merlot and Cabernet Franc; some Syrah and Zinfandel.', 'Dry whites from Chardonnay and Sauvignon Blanc, and Bordeaux-variety reds.', array['Established 1983 (27 CFR 9.52)', 'More than 1,400 acres of vineyard and five wineries (Sonoma County Tourism)', 'Elevations reach about 1,600 feet (Sonoma County Tourism)', 'Labels must also show "Sonoma County" (Cal. Bus. & Prof. Code §25246)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.north-coast.northern-sonoma.russian-river-valley.chalk-hill';
