-- united-states.california.north-coast.northern-sonoma.russian-river-valley.green-valley-of-russian-river-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'The coolest, foggiest corner of the Russian River Valley, in wooded hills between Sebastopol, Occidental and Forestville, following the watersheds of Green Valley, Atascadero and Purrington creeks. Apple orchards shared the land with vines for decades. It was called Sonoma County Green Valley until 2007, when it was renamed to avoid confusion with Solano County Green Valley.', 'Fog arrives early and stays late: the hills trap it, so days are cool and the range between day and night is narrow; sheltered from much of the wind.', 'Goldridge fine sandy loam dominates: well drained, deep-rooting, and moderately vigorous, with enough clay to hold some moisture in dry years.', 'Pinot Noir and Chardonnay, with Syrah a distant third.', 'Dry Pinot Noir and Chardonnay, and sparkling wine from both.', array['Established 1983 (27 CFR 9.57)', 'Named Sonoma County Green Valley from 1983 until 2007 (27 CFR 9.57)', 'About 19,000 acres, 3,600 of them planted (Sonoma County Tourism)', 'Labels must also show "Sonoma County" (Cal. Bus. & Prof. Code §25246)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.north-coast.northern-sonoma.russian-river-valley.green-valley-of-russian-river-valley';
