-- united-states.california.north-coast.petaluma-gap
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A wind-defined AVA of about 202,500 acres across southern Sonoma County and northern Marin County, from the Pacific to San Pablo Bay. A gap in the coastal hills lets ocean wind and fog flow inland, and the AVA is drawn around that corridor. Pinot Noir is about three quarters of its vineyard.', 'Windy and cool: afternoon wind through low hills of under 600 feet lowers photosynthesis, so grapes hang longer, with smaller berries and thicker skins, and can be picked at lower sugar.', 'Varied soils on low rolling hills; the petition defined the area by its wind rather than its soils.', 'Pinot Noir about 75% of the vineyard, then Chardonnay and Syrah.', 'Dry Pinot Noir, Chardonnay and Syrah, and some sparkling wine.', array['Established 2017 (27 CFR 9.261)', 'Spans Sonoma and Marin counties', 'About 80 vineyards on some 4,000 acres at the petition (TTB final rule)', 'Pinot Noir 75%, Chardonnay 13%, Syrah 12% of the vineyard (Sonoma County Tourism)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.north-coast.petaluma-gap';
