-- united-states.california.north-coast.pine-mountain-cloverdale-peak
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A mountain AVA of about 4,600 acres on the ridges northeast of Cloverdale, along Pine Mountain Road, crossing from Sonoma into Mendocino County. Only land above the 1,600-foot contour is included, and about 230 acres are planted, around 80% of them to Cabernet Sauvignon.', 'Often above morning fog: days are cooler and lightly breezy, nights warmer than in the valleys below.', 'Mountain soils among oak woodland, madrone and scrub, with spring-fed ponds between the vineyard blocks.', 'Cabernet Sauvignon about 80% of the vineyard, with Merlot, Malbec and Cabernet Franc.', 'Dry red wines, mainly Cabernet Sauvignon.', array['Established 2011 (27 CFR 9.220)', 'Spans Sonoma and Mendocino counties', 'Its boundary follows the 1,600-foot contour line (27 CFR 9.220)', 'About 230 of 4,600 acres planted (Sonoma County Tourism)']::text[], 'PUBLISHED'
