-- united-states.california.north-coast.rockpile
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A ridge-top AVA in northwest Sonoma County, above Dry Creek Valley and overlooking Lake Sonoma. It covers only ground above the 800-foot contour; of some 15,000 acres, about 160 are planted, mostly since 1992. It is known for Zinfandel.', 'Sunny, with less fog than the valleys below: an inversion layer from Lake Sonoma keeps the fog beneath the vineyards.', 'Upland soils on steep ridges; before vines the area was sheep ranches and hunting clubs for about a century.', 'Zinfandel first, with Cabernet Sauvignon, Petite Sirah and Syrah.', 'Dry red wines, above all Zinfandel, and some Petite Sirah and Syrah.', array['Established 2002 (27 CFR 9.173)', 'Its boundary mostly follows the 800-foot contour line (27 CFR 9.173)', 'Elevations from about 800 to 2,100 feet (Sonoma County Tourism)', 'Labels must also show "Sonoma County" (Cal. Bus. & Prof. Code §25246)']::text[], 'PUBLISHED'
