-- united-states.california.north-coast.sonoma-coast
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'Sonoma County''s largest AVA, reaching from the wind-swept Pacific coast in the north to the salt marshes of San Pablo Bay in the south. It holds West Sonoma Coast and Fort Ross-Seaview, and overlaps the Russian River Valley and Los Carneros. Pinot Noir and Chardonnay are its main grapes.', 'Shaped by the Pacific: afternoon fog covers the lower ground while ridge-top vineyards often rise above it, and wind and fog pour in through the Petaluma Gap in the south.', 'Varied: thin, sandy soils over Franciscan rocks on the coastal ridges and heavy adobe clays near San Pablo Bay in the south.', 'Pinot Noir and Chardonnay, with Syrah as a runner-up and some Zinfandel.', 'Dry Pinot Noir and Chardonnay, and sparkling wine.', array['Established 1987 (27 CFR 9.116)', 'Sonoma County''s largest AVA (Sonoma County Tourism)', 'Contains West Sonoma Coast (2022) and Fort Ross-Seaview (2011)', 'Labels must also show "Sonoma County" (Cal. Bus. & Prof. Code §25246)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.north-coast.sonoma-coast';
