-- united-states.california.north-coast.sonoma-coast.west-sonoma-coast
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'The westernmost strip of Sonoma County, about 141,800 acres of steep coastal ridges along the San Andreas fault, from Annapolis in the north through Fort Ross-Seaview to Freestone and Occidental. It lies within Sonoma Coast and holds all of Fort Ross-Seaview. At establishment it had about 47 commercial vineyards and some 1,028 acres of vines.', 'Marine: days cooler and nights warmer than inland, fewer growing degree days than to the east, and less wind than the Petaluma Gap to the south; many vineyards sit above the fog.', 'Thin, sandy, well-drained soils over hard Franciscan Complex rocks, unlike the Wilson Grove Formation farther east.', 'Pinot Noir and Chardonnay, with some Syrah.', 'Dry Pinot Noir and Chardonnay, and some Syrah.', array['Established 2022 (27 CFR 9.283)', 'About 141,846 acres (TTB final rule)', 'About 47 commercial vineyards and 1,028 acres of vines at establishment (TTB final rule)', 'Labels must also show "Sonoma County" (Cal. Bus. & Prof. Code §25246)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.north-coast.sonoma-coast.west-sonoma-coast';
