-- united-states.california.north-coast.sonoma-coast.west-sonoma-coast.fort-ross-seaview
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'Ridge-top land above Fort Ross State Historic Park, between Jenner and The Sea Ranch, overlooking the Pacific. The AVA covers only ground above the 920-foot contour, so its vineyards sit above the marine layer. Russian settlers planted grapes at Fort Ross in 1817; modern planting began in 1973.', 'Cool and close to the cold Pacific, but above the fog: the ridges get more summer sun than the coast and valleys below.', 'Thin, well-drained soils on steep coastal ridges over Franciscan rocks.', 'Pinot Noir and Chardonnay, with some Syrah and Zinfandel.', 'Dry Pinot Noir and Chardonnay from ridge-top vineyards.', array['Established 2011 (27 CFR 9.221)', 'Its boundary mostly follows the 920-foot contour line (27 CFR 9.221)', 'About 27,500 acres with about 500 acres of vineyard (Sonoma County Tourism)', 'Labels must also show "Sonoma County" (Cal. Bus. & Prof. Code §25246)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.north-coast.sonoma-coast.west-sonoma-coast.fort-ross-seaview';
