-- united-states.california.north-coast.sonoma-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'The valley of Sonoma Creek in southeast Sonoma County, between the Mayacamas range and Sonoma Mountain, from Sugarloaf Ridge down to San Pablo Bay, with the town of Sonoma at its heart. Commercial winemaking in California began here in the 1850s, and old Zinfandel plantings date from then. It holds Bennett Valley, Moon Mountain District and Sonoma Mountain.', 'Three zones: mild days and cool bay winds in the flat south near Carneros, warmer around Glen Ellen where Sonoma Mountain holds the heat, and cooler again in the north around Kenwood, where Pacific fog and wind reach.', 'Fertile, loamy soils that hold water on the valley floor, and meagre, rocky, well-drained soils higher up the slopes.', 'Cabernet Sauvignon is now the leading grape, with old-vine Zinfandel, Merlot, Chardonnay, Pinot Noir and Syrah.', 'Dry red wines from Cabernet Sauvignon and Zinfandel, and dry Chardonnay.', array['Established 1981 (27 CFR 9.29)', 'More than 14,000 acres of vineyard (Sonoma County Tourism)', 'Commercial winemaking in California began here in the 1850s (Sonoma County Tourism)', 'Labels must also show "Sonoma County" (Cal. Bus. & Prof. Code §25246)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.north-coast.sonoma-valley';
