-- united-states.california.north-coast.sonoma-valley.bennett-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A small upland valley south of Santa Rosa, ringed by Sonoma Mountain, Bennett Peak and Taylor Mountain, on high ground between Sonoma Valley and the Cotati Valley. Isaac DeTurk founded a winery here in 1862; after phylloxera and Prohibition the vines returned in the late 1970s with Matanzas Creek. About 650 acres are planted.', 'Cool: Pacific air and fog reach it through the Petaluma Gap and Crane Canyon on summer afternoons.', 'Clay-like volcanic soils on the valley floor and the surrounding slopes.', 'Merlot and Chardonnay made its name, with Cabernet Sauvignon, Pinot Noir, Syrah and Sauvignon Blanc.', 'Dry Merlot, Chardonnay and Pinot Noir, and some Syrah.', array['Established 2003 (27 CFR 9.142)', 'About 650 acres of vineyard (Sonoma County Tourism)', 'Isaac DeTurk founded the Belle Mount winery here in 1862 (Sonoma County Tourism)', 'Labels must also show "Sonoma County" (Cal. Bus. & Prof. Code §25246)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.north-coast.sonoma-valley.bennett-valley';
