-- united-states.california.north-coast.sonoma-valley.moon-mountain-district-sonoma-county
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'The western slopes of the Mayacamas range above Sonoma Valley, facing Sonoma Mountain across the valley, from about 200 to 2,200 feet. About 1,500 of its 17,663 acres are planted. It holds the Monte Rosso vineyard, first planted in 1886 and named by Louis M. Martini in 1938. The legal name already includes "Sonoma County".', 'Afternoon sun with crosswinds from the Pacific and San Pablo Bay; the higher vineyards get stronger sun.', 'Rocky, iron-rich volcanic soils and loams.', 'Zinfandel and Cabernet Sauvignon, with Merlot, Cabernet Franc, Petit Verdot, Malbec and some Chardonnay.', 'Dry red wines, mostly Cabernet Sauvignon and old-vine Zinfandel.', array['Established 2013 (27 CFR 9.231)', '17,663 acres, about 1,500 of them planted (Sonoma County Tourism)', 'Elevations from about 200 to 2,200 feet (Sonoma County Tourism)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.north-coast.sonoma-valley.moon-mountain-district-sonoma-county';
