-- united-states.california.north-coast.sonoma-valley.sonoma-mountain
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'The north and east slopes of Sonoma Mountain above Glen Ellen, in the northwest of Sonoma Valley, between about 400 and 1,200 feet. Its vineyards are scattered among woods and grazing land; Jack London farmed here. About 800 acres are planted.', 'The eastern slopes are sheltered from fog, sunny and warm; the western flank gets cool wind and fog from the Petaluma Gap.', 'Hillside soils on a series of stacked hills dotted with live oak, the vineyards isolated among woods and grazing land.', 'Cabernet Sauvignon on the warm eastern side, Pinot Noir on the western side, with Chardonnay, Syrah, Sauvignon Blanc and Zinfandel.', 'Dry Cabernet Sauvignon and Pinot Noir, and dry Chardonnay.', array['Established 1985 (27 CFR 9.102)', 'About 800 acres of vineyard (Sonoma County Tourism)', 'Elevations from about 400 to 1,200 feet (Sonoma County Tourism)', 'Labels must also show "Sonoma County" (Cal. Bus. & Prof. Code §25246)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.north-coast.sonoma-valley.sonoma-mountain';
