-- united-states.california.north-coast.wild-horse-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A small upland AVA in the hills east of the city of Napa, straddling the line between Napa and Solano counties. Most of it lies above the fog, and its vineyards were first planted in 1881 and replanted from 1978. Chardonnay and Pinot Noir are its main grapes.', 'The coolest of the AVAs that reach into Napa Valley, because of its height and San Pablo Bay nearby; summer days rarely pass 90 °F and the difference between day and night is small.', 'Shallow volcanic soils with little water-holding capacity, so irrigation is usually needed.', 'Chardonnay and Pinot Noir, planted from 1978 on.', 'Dry Chardonnay and Pinot Noir from upland vineyards.', array['Established 1988 (27 CFR 9.124)', 'Spans Napa and Solano counties', 'Elevations from about 850 to 2,130 feet (Napa Valley Vintners)', 'Rainfall up to about 35 inches a year (Napa Valley Vintners)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.north-coast.wild-horse-valley';
