-- united-states.california.south-coast.temecula-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An inland valley in southwestern Riverside County, with vineyards at about 1,400 to 1,600 feet between the coastal mountains and Mount San Jacinto. Cool Pacific air reaches it each afternoon through the Rainbow Gap and the Santa Margarita Gap in the coastal mountains. It was called Temecula until 2004.', 'Warm days and cool nights: around late morning, heat over the desert to the east draws cool ocean air through the gaps, and the day-to-night swing can reach 40 to 50 °F.', 'Decomposed granite, rocky and sandy loams.', 'Cabernet Sauvignon is the most planted, with Syrah, Chardonnay, Merlot, and Mediterranean varieties such as Sangiovese, Tempranillo and Viognier.', 'Dry reds from Bordeaux and Mediterranean varieties, dry whites and rosé.', array['Established 1984 (27 CFR 9.50)', 'Named Temecula until June 2004 (27 CFR 9.50)', 'Its boundary uses the 1,400- and 1,500-foot contour lines in places (27 CFR 9.50)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.south-coast.temecula-valley';
